This Go program is meant to print the squares of 0..4 using goroutines, but the output is wrong and it may deadlock or exit early. Find all the bugs and fix them.

package main

import (
    "fmt"
    "sync"
)

func main() {
    var wg sync.WaitGroup
    results := make(chan int)
    for i := 0; i < 5; i++ {
        go func() {
            wg.Add(1)
            defer wg.Done()
            results <- i * i
        }()
    }
    wg.Wait()
    close(results)
    for r := range results {
        fmt.Println(r)
    }
}

