Refactor this callback-style Node.js code to TypeScript async/await. Constraints: retry the fetch up to 3 times with exponential backoff (100ms, 200ms) only on network errors, not on HTTP 4xx, and preserve the final error if all attempts fail.

function getUser(id, cb) {
  http.get('/users/' + id, function (err, res) {
    if (err) return cb(err);
    if (res.status !== 200) return cb(new Error('bad status ' + res.status));
    parse(res.body, function (err2, user) {
      if (err2) return cb(err2);
      cb(null, user);
    });
  });
}

Write JUnit 5 tests for the following class. Cover normal behavior and edge cases, and point out any bug you find in the class.

public class BoundedStack<T> {
    private final Object[] data;
    private int size = 0;

    public BoundedStack(int capacity) { data = new Object[capacity]; }

    public void push(T item) {
        data[size++] = item;
    }

    @SuppressWarnings("unchecked")
    public T pop() {
        if (size == 0) throw new IllegalStateException("empty");
        return (T) data[--size];
    }

    public int size() { return size; }
}

This binary search sometimes loops forever. Find the bug, fix it, and explain which inputs trigger it.

def bsearch(arr, target):
    lo, hi = 0, len(arr) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if arr[mid] < target:
            lo = mid
        else:
            hi = mid
    return lo if arr and arr[lo] == target else -1

